-- Rodos Modern INSIDE: точні кольори, види полотна й фото з офіційних карток Rodos.
-- Скрипт не змінює інші колекції або бренди. Кожна модель очищається тільки перед повторним наповненням її конфігуратора.
do $$ begin if (select count(*) from public.products where slug in ('rodos-official-rexzia','rodos-official-1yz0ngg','rodos-official-1utgp0n','rodos-official-14efvk6')) <> 4 then raise exception 'Не знайдено всі моделі Rodos Modern INSIDE для пакета — каталог не змінено'; end if; end $$;
begin;
delete from public.product_options where product_slug = 'rodos-official-rexzia';
delete from public.product_variants where product_slug = 'rodos-official-rexzia';
delete from public.product_media where product_slug = 'rodos-official-rexzia' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-1yz0ngg';
delete from public.product_variants where product_slug = 'rodos-official-1yz0ngg';
delete from public.product_media where product_slug = 'rodos-official-1yz0ngg' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-1utgp0n';
delete from public.product_variants where product_slug = 'rodos-official-1utgp0n';
delete from public.product_media where product_slug = 'rodos-official-1utgp0n' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-14efvk6';
delete from public.product_variants where product_slug = 'rodos-official-14efvk6';
delete from public.product_media where product_slug = 'rodos-official-14efvk6' and label like 'config:%';
commit;
select product_slug, count(*) filter (where option_group = 'color') as кольорів, count(*) filter (where option_group = 'configuration') as видів_полотна from public.product_options where product_slug in ('rodos-official-rexzia','rodos-official-1yz0ngg','rodos-official-1utgp0n','rodos-official-14efvk6') group by product_slug order by product_slug;